return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 0 || n % 100 >= 11 && n % 100 <= 19) ? 0 : ((n % 10 == 1 && n % 100 != 11) ? 1 : 2);','language'=>'lv','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:50:59+00:00','po-revision-date'=>'2026-11-05T19:50:59+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Papildina trūkstošos tulkojumus spraudņiem un tēmām, kas jau ir instalētas jūsu vietnē.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Šis augšupielādes ekrāns bija novecojis: kopš tā laika ir sagatavota cita augšupielāde. Nekas netika nosūtīts. Pārskatiet pašreizējo augšupielādi sadaļā Tulkojumu saraksts.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Bezmaksas pakalpojuma plāns katrai vietnei nodrošina ierobežotu skaitu vietu spraudņiem un tēmām; izmantotās vietas tiek rādītas sadaļā Iestatījumi pēc Babilim iespējošanas.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Tulkojuma pieprasīšana ievieto šo spraudni vai tēmu vienā no bezmaksas pakalpojuma plāna vietām šai vietnei (ierobežojums ir %1$d tēmām un %2$d spraudņiem), ja vien tam vēl nav vietas. Vieta paliek izmantota, un neveiksmīgs tulkojums to neatbrīvo.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Tulkojuma pieprasīšana ievieto šo spraudni vai tēmu vienā no bezmaksas pakalpojuma plāna vietām šai vietnei, ja vien tam vēl nav vietas. Vieta paliek izmantota, un neveiksmīgs tulkojums to neatbrīvo.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Ja šis spraudnis vai tēma vēl nav vienā no bezmaksas pakalpojuma plāna vietām šai vietnei, tulkojuma pieprasīšana to ievieto vienā no tām (ierobežojums ir %1$d tēmām un %2$d spraudņiem). Vieta paliek izmantota, un neveiksmīgs tulkojums to neatbrīvo. Vai turpināt?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Ja šis spraudnis vai tēma vēl nav vienā no bezmaksas pakalpojuma plāna vietām šai vietnei, tulkojuma pieprasīšana to ievieto vienā no tām. Vieta paliek izmantota, un neveiksmīgs tulkojums to neatbrīvo. Vai turpināt?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d vietne šajā tīklā ir iestatīta izdzēst savu Babilim identitāti, kad spraudnis tiek dzēsts. Šai vietnei piesaistīto maksas licenci tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %2$s. Lai saglabātu identitāti, nospiediet Atcelt, šīs vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?' . "\0" . '%1$d vietnes šajā tīklā ir iestatītas izdzēst savu Babilim identitāti, kad spraudnis tiek dzēsts. Šīm vietnēm piesaistītās maksas licences tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %2$s. Lai saglabātu identitātes, nospiediet Atcelt, katras vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?' . "\0" . 'Šajā tīklā ir %1$d vietņu, kurām iestatīta Babilim identitātes dzēšana, kad spraudnis tiek dzēsts. Šīm vietnēm piesaistītās maksas licences tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %2$s. Lai saglabātu identitātes, nospiediet Atcelt, katras vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nav ko darīt.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Izvēlieties valodu.','%d failed'=>'%d neizdevās' . "\0" . '%d neizdevās' . "\0" . '%d neizdevās','%d not yet tried'=>'%d vēl nav mēģināts' . "\0" . '%d vēl nav mēģināti' . "\0" . '%d vēl nav mēģināti','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'Gaida %d ziņojums. Izvēles “Vienmēr kopīgot” un “Nekopīgot” attiecas uz visiem.' . "\0" . 'Gaida %d ziņojumi. Izvēles “Vienmēr kopīgot” un “Nekopīgot” attiecas uz visiem.' . "\0" . 'Gaida %d ziņojumu. Izvēles “Vienmēr kopīgot” un “Nekopīgot” attiecas uz visiem.','%d skipped'=>'%d izlaists' . "\0" . '%d izlaisti' . "\0" . '%d izlaisti','%d succeeded'=>'%d veiksmīgi' . "\0" . '%d veiksmīgi' . "\0" . '%d veiksmīgi','%d to install'=>'%d instalēšanai' . "\0" . '%d instalēšanai' . "\0" . '%d instalēšanai','(a public key generated for this site)'=>'(šai vietnei ģenerēta publiskā atslēga)','(detected)'=>'(noteikts)','(generic codes and coordinates only)'=>'(tikai vispārīgi kodi un koordinātas)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Tīrīšana tika apturēta %1$s: %2$s. Nekas netika dzēsts.','A file in the component could not be read, so it was not packaged.'=>'Kādu komponenta failu nevarēja nolasīt, tāpēc tas netika iekļauts pakotnē.','A host that serves only one PHP request at a time cannot complete this step.'=>'Resursdators, kas vienlaikus apkalpo tikai vienu PHP pieprasījumu, šo darbību nevar pabeigt.','A part of the upload kept failing, so the upload was cancelled.'=>'Kāda augšupielādes daļa atkārtoti neizdevās, tāpēc augšupielāde tika atcelta.','A translation cannot be requested for that locale on this site right now.'=>'Šobrīd šajā vietnē nevar pieprasīt tulkojumu šai lokalizācijai.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Tulkojumu indeksa ieraksts %1$s (%2$s) konfliktēja ar citu pieprasījumu un netika lietots; saglabāta jaunākā versija.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Tulkojumu indeksa ierakstu %1$s (%2$s) neizdevās pabeigt, un tas netika lietots (%3$s).','Account'=>'Konts','Add another language'=>'Pievienot citu valodu','Advanced'=>'Papildu','All'=>'Visi','All free-plan slots for this site are used'=>'Visas šīs vietnes bezmaksas plāna vietas ir izmantotas','All languages'=>'Visas valodas','Already in WordPress core'=>'Jau ir WordPress kodolā','Already installed.'=>'Jau instalēts.','Always share'=>'Vienmēr kopīgot','Another installation is running; try again in a moment.'=>'Notiek cita instalēšana; mēģiniet vēlreiz pēc brīža.','Automatic installs'=>'Automātiskā instalēšana','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automātiskā instalēšana tagad ir izslēgta; ja vēlaties, iespējojiet to atkal iestatījumos.','Available'=>'Pieejami','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Pieejamos tulkojumus var instalēt ar vienu klikšķi, un trūkstošos var pieprasīt. Kamēr automātiskās instalēšanas ir ieslēgtas, tulkojumi, kurus pakalpojums norāda kā pieejamus jūsu pārvaldītajām valodām, tiek instalēti sinhronizācijas laikā divreiz dienā.','Available · %s'=>'Pieejams · %s','Babilim Settings'=>'Babilim iestatījumi','Babilim adds translations for every language checked here.'=>'Babilim pievieno tulkojumus katrai šeit atzīmētajai valodai (Valoda).','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim nevarēja apstiprināt pagaidu mapi ārpus vietnes, tāpēc komponente netika iepakota un nekas netika augšupielādēts. Definējiet BABILIM_TEMP_DIR failā wp-config.php kā rakstāmu mapi ārpus tīmekļa saknes direktorijas (piemēram, mapi blakus jūsu vietnes publiskajai direktorijai, nevis tās iekšpusē) vai pieprasiet to savam hostinga sniedzējam.','Babilim could not finish checking this site.'=>'Babilim nevarēja pabeigt šīs vietnes pārbaudi.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nevarēja pabeigt iespējošanu (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nevarēja pabeigt šīs vietnes verifikāciju (pakalpojums nevarēja izveidot atpakaļsavienojumu ar vietni). Reģistrācija ir apturēta.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nevarēja pārbaudīt šo vietni, tāpēc nekas netiks lejupielādēts vai instalēts, kamēr pārbaude nebūs sekmīga.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nevarēja verificēt šo vietni, tāpēc nekas netiek lejupielādēts vai instalēts.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim atrod šīs vietnes spraudņus un tēmas, kurām nav tulkojuma jūsu valodā, un katrai instalē tulkojumu.','Babilim has not been enabled for this site yet.'=>'Babilim šai vietnei vēl nav iespējots.','Babilim has not installed any translation for this language.'=>'Babilim nav instalējis nevienu tulkojumu šai valodai.','Babilim hit an error. Share an error report?'=>'Babilim radās kļūda. Vai kopīgot kļūdas ziņojumu?','Babilim installed %d translation automatically since your last visit.'=>'Babilim kopš jūsu pēdējā apmeklējuma automātiski instalēja %d tulkojumu.' . "\0" . 'Babilim kopš jūsu pēdējā apmeklējuma automātiski instalēja %d tulkojumus.' . "\0" . 'Babilim kopš jūsu pēdējā apmeklējuma automātiski instalēja %d tulkojumus.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ir atspējots. Vairs nekas netiek sūtīts; jau instalētie tulkojumi turpina darboties.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim ir iespējots: šī vietne ir verificēta un atrasts %d komponents.' . "\0" . 'Babilim ir iespējots: šī vietne ir verificēta un atrasti %d komponenti.' . "\0" . 'Babilim ir iespējots: šī vietne ir verificēta un atrasti %d komponenti.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim iespējo un pārbauda šo vietni… (pēdējais mēģinājums: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim iespējo un pārbauda šo vietni… Pārlādējiet lapu vai uzgaidiet, līdz tiek pabeigta ieplānotā pārbaude.','Babilim is not enabled.'=>'Babilim nav iespējots.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim ir iestatīts izdzēst šīs vietnes identitāti, kad spraudnis tiek dzēsts. Šai vietnei piesaistīto maksas licenci tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %s. Lai saglabātu identitāti, nospiediet Atcelt, Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?','Babilim ran out of time for this step and will continue on the next check.'=>'Šim solim Babilim pietrūka laika, un tas turpinās nākamajā pārbaudē.','Babilim settings'=>'Babilim iestatījumi','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim sinhronizāciju pakalpojums īslaicīgi aizkavē (ierobežots pieprasījumu skaits); tā mēģinās vēlreiz pēc %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim tika atjaunināts, kamēr šī augšupielāde gaidīja. Vecā pakotne tika atmesta; lūdzu, apstipriniet augšupielādi vēlreiz.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim augšupielādēs šos failus no %1$s (versija %2$s): visus .php un .js failus, visus block.json failus, kā arī readme.txt, readme.md, style.css un theme.json tā galvenajā mapē. Tie tiek izmantoti, lai atrastu tekstu, kas jātulko, un lai identificētu spraudni vai tēmu.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nav pieejams: %s','Back'=>'Atpakaļ','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Vai jau esat iegādājies licenci šim domēnam? Ievadiet atjaunošanas kodu, ko saņēmāt norēķina laikā.','Broken placeholder'=>'Bojāts vietturis','Build'=>'Būvējums','Built'=>'Izveidots','Bulk actions apply only to the selected language of each selected component.'=>'Masveida darbības tiek piemērotas tikai katra atlasītā komponenta atlasītajai valodai.','Bulk actions apply to every matching language of each selected component.'=>'Masveida darbības attiecas uz katru atbilstošo valodu katram atlasītajam komponentam.','Bulk download:'=>'Masveida lejupielāde:','Bulk request:'=>'Masveida pieprasīšana:','Bulk update:'=>'Masveida atjaunināšana:','Bundled with the plugin'=>'Iekļauts spraudnī','Bundled with the theme'=>'Iekļauts tēmā','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Noklikšķinot uz Iespējot, jūs piekrītat nosūtīt Babilim iepriekš norādīto informāciju.','By continuing you confirm that you have the right to upload this component.'=>'Turpinot, jūs apliecināt, ka jums ir tiesības augšupielādēt šo komponentu.','Cancel'=>'Atcelt','Category'=>'Kategorija','Check again'=>'Pārbaudīt vēlreiz','Check again now'=>'Pārbaudīt vēlreiz tagad','Checkout is not available for this site right now.'=>'Norēķini šai vietnei pašlaik nav pieejami.','Choose'=>'Izvēlēties','Choose a category…'=>'Izvēlieties kategoriju…','Choose a language'=>'Izvēlieties valodu','Choose a language…'=>'Izvēlieties valodu…','Clear filters'=>'Notīrīt filtrus','Close'=>'Aizvērt','Component'=>'Komponents','Confirm'=>'Apstiprināt','Conflicting keys'=>'Konfliktējošās atslēgas','Continue'=>'Turpināt','Continue next batch (%d left)'=>'Turpināt ar nākamo partiju (atlikušas %d)','Continuing…'=>'Turpina…','Could not back up %s before replacing it.'=>'Nevarēja izveidot %s rezerves kopiju pirms tā aizstāšanas.','Could not create the package archive.'=>'Neizdevās izveidot pakotnes arhīvu.','Could not determine active components; the existing merged index was left unchanged.'=>'Neizdevās noteikt aktīvos komponentus; esošais apvienotais indekss tika atstāts nemainīts.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Neizdevās noteikt instalētos spraudņus/tēmas; tīrīšana izlaista, nekas netika dzēsts.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Neizdevās ielādēt pilnu WordPress.org lokalizāciju sarakstu no pakalpojuma, tāpēc pašlaik nevar pievienot citas valodas.','Could not move %s into place.'=>'Neizdevās pārvietot %s uz paredzēto vietu.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Neizdevās novietot apvienoto indeksu lokalizācijai \'%s\' paredzētajā vietā; iepriekšējais sniegtais indekss (ja tāds bija) tika noņemts, nevis atstāts daļēji atjaunināts. Šai lokalizācijai netiek sniegts noklusējuma domēna papildinājums līdz nākamajai sekmīgajai pārbūvei.','Could not open zip: %s'=>'Neizdevās atvērt zip: %s','Could not prepare %s for rollback.'=>'Neizdevās sagatavot %s atcelšanai.','Could not read %s back after moving it into place.'=>'Neizdevās atkārtoti nolasīt %s pēc tā novietošanas paredzētajā vietā.','Could not read: %s'=>'Nevarēja nolasīt: %s','Could not restore the purchase: %s'=>'Neizdevās atjaunot pirkumu: %s','Could not show a new restore code: %s'=>'Neizdevās parādīt jaunu atjaunošanas kodu: %s','Could not stage %s'=>'Nevarēja sagatavot %s','Could not stage default/%s'=>'Nevarēja sagatavot default/%s','Could not start checkout: %s'=>'Neizdevās sākt norēķinu: %s','Could not verify entry count for %s'=>'Nevarēja pārbaudīt ierakstu skaitu failam %s','Could not write the downloaded package to disk.'=>'Neizdevās ierakstīt lejupielādēto pakotni diskā.','Could not write the staged merged index.'=>'Neizdevās ierakstīt sagatavoto apvienoto indeksu.','Current translation'=>'Pašreizējais tulkojums','Custom overrides'=>'Pielāgoti pārrakstījumi','Danger zone'=>'Bīstamā zona','Default supplement entry count mismatch.'=>'Noklusējuma papildinājuma ierakstu skaita neatbilstība.','Delete all Babilim data on uninstall'=>'Atinstalējot dzēst visus Babilim datus','Disable Babilim'=>'Atspējot Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Atspējot Babilim? Instalētie tulkojumi tiks saglabāti, taču turpmākas pārbaudes vai lejupielādes netiks veiktas.','Don\'t share'=>'Nekopīgot','Download'=>'Lejupielādēt','Downloaded and installed.'=>'Lejupielādēts un instalēts.','Downloading…'=>'Lejupielādē…','Downloads: %1$d/%2$d (%3$s)'=>'Lejupielādes: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Katra komponenta ieguldījums katras lokalizācijas kopīgajā noklusējuma domēna papildinājumā.','Enable Babilim'=>'Iespējot Babilim','Enabling…'=>'Iespējo…','English (United States)'=>'Angļu (Amerikas Savienotās Valstis)','Entries'=>'Ieraksti','Entry count mismatch for %s'=>'Ierakstu skaita neatbilstība failam %s','Error reports'=>'Kļūdu ziņojumi','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Katrs instalētais spraudnis vai tēma: tā identifikators (slug), versija, teksta domēni, vai tas ir iekļauts wp.org katalogā, komplektā iekļautās lokāles un lokāles, kurām jau esat instalējis Babilim tulkojumu.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Visas šajā vietnē izmantotās lokāles (vietnes lokāle, instalētās valodas pakotnes, lietotāju lokāles un visas manuāli pievienotās lokāles). Neviena lokāle netiek traktēta citādi nekā cita.','Excluded'=>'Izslēgts','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Faili ar citiem nosaukumiem vai paplašinājumiem netiek iekļauti, kā arī netiek iekļautas mapes uploads, cache, logs, backup, data, vendor, node_modules un languages, slēptie faili vai faili, kuru nosaukumi atbilst bieži sastopamiem noslēpumiem (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Koda faili tomēr var saturēt tekstu vai datus, ko nevēlaties kopīgot; pārbaudiet tos, ja neesat pārliecināts. Pakalpojums saņemšanas brīdī atkal noņem tādus pašus failu veidus.','Free'=>'Bezmaksas','Free-plan slots'=>'Bezmaksas plāna vietas','General'=>'Vispārīgi','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ja šī opcija ir ieslēgta, atinstalēšana izdzēš arī šīs vietnes identitāti. Šai vietnei piesaistīto maksas licenci pēc tam nevar atjaunot automātiski; lai to atgūtu, jums būs jāsazinās ar Babilim atbalstu pa adresi %s.','Included'=>'Iekļauts','Included in index'=>'Iekļauts indeksā','Install available translations automatically'=>'Automātiski instalēt pieejamos tulkojumus','Installed'=>'Instalēti','Installed translations are kept, but no further checks or downloads will run.'=>'Instalētie tulkojumi tiks saglabāti, taču turpmākas pārbaudes vai lejupielādes netiks veiktas.','Installed · %s'=>'Instalēts · %s','Installed · built for %1$s, this site has %2$s'=>'Instalēts · izveidots versijai %1$s, šajā vietnē ir %2$s','Installed · built for %s'=>'Instalēts · izveidots versijai %s','Installed · built for %s, all free-plan slots for this site are used'=>'Instalēts · izveidots versijai %s, visas šīs vietnes bezmaksas plāna vietas ir izmantotas','Installed · built for %s, new version failed'=>'Instalēts · izveidots versijai %s, jaunā versija neizdevās','Installed · built for %s, new version not covered by the free service plan'=>'Instalēts · izveidots versijai %s, jaunā versija nav iekļauta bezmaksas pakalpojuma plānā','Installed · built for %s, new version scheduled'=>'Instalēts · izveidots versijai %s, jaunā versija ieplānota','Installed · built for %s, translating the new version…'=>'Instalēts · izveidots versijai %s, notiek jaunās versijas tulkošana…','Installed · built for a different version'=>'Instalēts · izveidots citai versijai','Installed · built for a different version, all free-plan slots for this site are used'=>'Instalēts · izveidots citai versijai, visas šīs vietnes bezmaksas plāna vietas ir izmantotas','Installed · built for a different version, new version failed'=>'Instalēts · izveidots citai versijai, jaunā versija neizdevās','Installed · built for a different version, new version not covered by the free service plan'=>'Instalēts · izveidots citai versijai, jaunā versija nav iekļauta bezmaksas pakalpojuma plānā','Installed · built for a different version, new version scheduled'=>'Instalēts · izveidots citai versijai, jaunā versija ieplānota','Installed · built for a different version, translating the new version…'=>'Instalēts · izveidots citai versijai, notiek jaunās versijas tulkošana…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'To glabā pakalpojuma mitināšanas sniedzējs, un tulkojuma izveidei to apstrādā mākslīgā intelekta modeļi.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Saglabāt manus pašu tulkojumu pārrakstījumus, dzēšot visu vai atinstalējot šo spraudni.','Language'=>'Valoda','Language:'=>'Valoda:','Languages'=>'Valodas','Languages found on this site: %s.'=>'Šajā vietnē atrastās valodas: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Pēdējā tīrīšana %1$s: no jauna atzīmēti faili: %2$d, dzēsti faili: %3$d, noņemti ieraksti: %4$d.','Maintenance'=>'Uzturēšana','Maintenance status is not available right now.'=>'Uzturēšanas statuss pašlaik nav pieejams.','Manifest unavailable: %s'=>'Manifests nav pieejams: %s','Negation reversed'=>'Apgriezts noliegums','No'=>'Nē','No build is available to download for this locale.'=>'Šai lokalizācijai nav pieejama lejupielādei piemērota versija.','No cleanup has run yet.'=>'Tīrīšana vēl nav veikta.','No components match these filters. %s'=>'Neviens komponents neatbilst šiem filtriem. %s','No components synced yet.'=>'Neviens komponents vēl nav sinhronizēts.','No installed translation matches.'=>'Nav atbilstošu instalēto tulkojumu.','No language is managed yet.'=>'Neviena valoda vēl netiek pārvaldīta.','No pending challenge for this nonce.'=>'Šim vienreizlietojamajam kodam (nonce) nav gaidošas izaicinājuma pārbaudes.','No pending challenge to verify.'=>'Nav neviena gaidoša izaicinājuma, ko pārbaudīt.','No plugins or themes found.'=>'Nav atrasts neviens spraudnis vai tēma.','No previous build to roll back to.'=>'Nav iepriekšēja būvējuma, uz kuru atgriezties.','No record for %s'=>'Nav ieraksta priekš %s','No site id is on file to rotate a token for.'=>'Nav saglabāta vietnes ID, kuram mainīt pilnvaru.','No — component inactive'=>'Nē — komponents nav aktīvs','No — component removed'=>'Nē — komponents noņemts','No — installed version differs from the active one'=>'Nē — instalētā versija atšķiras no aktīvās','Not a valid server_build_id: %s'=>'Nederīgs server_build_id: %s','Not covered by the free service plan'=>'Nav iekļauts bezmaksas pakalpojuma plānā','Not installed'=>'Nav instalēts','Not registered yet'=>'Vēl nav reģistrēts','Not supported'=>'Netiek atbalstīts','Not verified'=>'Nav pārbaudīts','Note (optional)'=>'Piezīme (nav obligāta)','Nothing to choose.'=>'Nav ko izvēlēties.','Nothing to confirm.'=>'Nav ko apstiprināt.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Pēc noklusējuma izslēgts: spraudņa dzēšana saglabā šīs vietnes identitāti, lai atkārtota instalēšana to varētu izmantot atkal.','One or more served files no longer match the manifest.'=>'Viens vai vairāki sniegtie faili vairs neatbilst manifestam.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Vienreizējs pirkums šai vietnei: %1$s %2$s. Ietver visus turpmākos tulkojumu atjauninājumus. Maksājumu apstrādā Paddle jaunā cilnē.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'To var izdarīt tikai tīkla administrators, jo tas maina tulkojumu failus, kas ir kopīgi visām šī tīkla vietnēm.','Only plugins and themes can be packaged.'=>'Pakot var tikai spraudņus un motīvus.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Tikai tad, kad apstiprināt augšupielādi spraudnim vai tēmai, kas nav pieejams WordPress.org: visi .php un .js faili, visi block.json faili, kā arī readme.txt, readme.md, style.css un theme.json šīs komponentes galvenajā mapē, zip arhīvā, izlaižot failus, kas atbilst bieži sastopamiem noslēpumiem.','Open Babilim settings'=>'Atvērt Babilim iestatījumus','Original language'=>'Oriģinālvaloda','Original string'=>'Oriģinālā virkne','Paid'=>'Maksas','Partner'=>'Partneris','Please check that your site can be reached from the internet, then try again.'=>'Lūdzu, pārbaudiet, vai jūsu vietne ir sasniedzama no interneta, un mēģiniet vēlreiz.','Please choose a category for this report.'=>'Lūdzu, izvēlieties šī ziņojuma kategoriju.','Plugin'=>'Spraudnis','Plugin · %s'=>'Spraudnis · %s','Plugins'=>'Spraudņi','Preview'=>'Priekšskatīt','Purchase restored. This site is now licensed.'=>'Pirkums atjaunots. Šai vietnei tagad ir licence.','Re-parsed entry count did not match the built index.'=>'Atkārtoti parsēto ierakstu skaits neatbilda izveidotajam indeksam.','Re-verify'=>'Verificēt vēlreiz','Rebuild index now'=>'Pārbūvēt indeksu tagad','Refusing to write outside the Babilim language-file directory.'=>'Atteikums rakstīt ārpus Babilim valodas failu direktorijas.','Registration response was missing required fields.'=>'Reģistrācijas atbildē trūka obligāto lauku.','Registration restarted.'=>'Reģistrācija sākta no jauna.','Remove'=>'Noņemt','Remove everything Babilim installed'=>'Noņemt visu, ko instalējis Babilim','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Vai noņemt visu, ko instalējis Babilim? Tas izdzēsīs visus valodas failus, ko tas instalējis visiem šīs vietnes spraudņiem un tēmām.','Remove the %2$s translation of %1$s from this site?'=>'Vai noņemt %1$s tulkojumu (%2$s) no šīs vietnes?','Removed %d installed component.'=>'Noņemts %d instalētais komponents.' . "\0" . 'Noņemti %d instalētie komponenti.' . "\0" . 'Noņemti %d instalētie komponenti.','Removed after a failed integrity check'=>'Noņemts pēc neveiksmīgas integritātes pārbaudes','Removed.'=>'Noņemts.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Noņem visus valodas failus, ko Babilim ir instalējis visiem šīs vietnes spraudņiem un tēmām.','Report a problem'=>'Ziņot par problēmu','Report translation'=>'Ziņot par tulkojumu','Request newer translation'=>'Pieprasīt jaunāku tulkojumu','Request translation'=>'Pieprasīt tulkojumu','Requestable'=>'Pieprasāms','Requesting…'=>'Pieprasa…','Restart registration'=>'Atsākt reģistrāciju','Restore code'=>'Atjaunošanas kods','Restore purchase'=>'Atjaunot pirkumu','Retry request'=>'Atkārtot pieprasījumu','Roll back'=>'Atritināt','Roll back and report'=>'Atritināt un ziņot','Roll back and send report'=>'Atritināt un nosūtīt ziņojumu','Roll back the %2$s translation of %1$s to the previous build?'=>'Vai atjaunot %1$s tulkojuma (%2$s) iepriekšējo būvējumu?','Rolled back and reported.'=>'Atgriezts un ziņots.','Rolled back to the previous build.'=>'Atgriezts uz iepriekšējo versiju.','Rolled back, but the report could not be sent: %s'=>'Atgriezts, bet ziņojumu nevarēja nosūtīt: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Atgriešana pārrakstītu \'%1$s\' (%2$s), ko tagad apkalpo citam instalētam komponentam (%3$s); nekas netika mainīts.','Rotate-token response was missing site_token.'=>'Atslēgas maiņas atbildē trūka site_token.','Save changes'=>'Saglabāt izmaiņas','Scheduled, waiting to be processed'=>'Ieplānots, gaida apstrādi','Search'=>'Meklēt','Search components'=>'Meklēt komponentus','Search the installed translations'=>'Meklēt instalētajos tulkojumos','Select all'=>'Atlasīt visu','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Atlasiet mazāk komponentu: vienā palaišanas reizē ne vairāk kā %1$d darbības (jūs atlasījāt %2$d).','Send report'=>'Nosūtīt ziņojumu','Service plan'=>'Pakalpojuma plāns','Settings'=>'Iestatījumi','Share error reports'=>'Kopīgot kļūdu ziņojumus','Share this report'=>'Kopīgot šo ziņojumu','Show a new restore code'=>'Parādīt jaunu atjaunošanas kodu','Show the "Report translation" entry in the admin toolbar'=>'Rādīt ierakstu “Ziņot par tulkojumu” administrēšanas rīkjoslā','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Daļu šī komponenta teksta autors ir iekodējis tieši kodā, un valodas pakotne to nevar tulkot.','Status'=>'Statuss','Status unknown'=>'Statuss nav zināms','String context'=>'Virknes konteksts','Suggested translation'=>'Ieteiktais tulkojums','Supplementary translation index'=>'Papildu tulkojumu indekss','Supplementary translation index rebuilt.'=>'Papildu tulkojumu indekss ir pārbūvēts.','Supplementary translation maintenance'=>'Papildu tulkojumu uzturēšana','Supplementary translations'=>'Papildu tulkojumi','Sweep aborted without orphaning anything: %s.'=>'Tīrīšana pārtraukta, nepārvēršot nevienu ierakstu par bezsaistes ierakstu: %s.','Sweep complete: %d file deleted.'=>'Tīrīšana pabeigta: izdzēsta %d datne.' . "\0" . 'Tīrīšana pabeigta: izdzēstas %d datnes.' . "\0" . 'Tīrīšana pabeigta: izdzēsts %d datņu.','Sweep now'=>'Tīrīt tagad','Sync complete.'=>'Sinhronizācija pabeigta.','Thank you. Your report was sent.'=>'Paldies. Jūsu ziņojums tika nosūtīts.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Šis komponents nav instalēts šajā vietnē, tāpēc tam nevar pieprasīt tulkojumu.','That does not look like a restore code.'=>'Tas neizskatās pēc atjaunošanas koda.','That is not a valid WordPress locale code. Nothing was saved.'=>'Šis nav derīgs WordPress lokalizācijas kods. Nekas netika saglabāts.','That is not a valid build identifier.'=>'Tas nav derīgs būvējuma identifikators.','The change could not be recorded in the translation index; please try again.'=>'Izmaiņas nevarēja ierakstīt tulkojumu indeksā; lūdzu, mēģiniet vēlreiz.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Tīrīšana tika veikta, taču dažas tās izmaiņas nevarēja ierakstīt tulkojumu indeksā; nākamā tīrīšana mēģinās vēlreiz.','The component has no files that can be uploaded.'=>'Komponentei nav failu, ko var augšupielādēt.','The component is not inside the plugins or themes directory.'=>'Komponents neatrodas spraudņu vai motīvu direktorijā.','The component\'s main file was not found.'=>'Komponenta galvenais fails netika atrasts.','The download response was missing a usable location.'=>'Lejupielādes atbildē trūka derīgas atrašanās vietas.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Ieraksts atver paneli, lai meklētu šajā vietnē Babilim instalētos tulkojumus un ziņotu par kādu no tiem.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Lauks "%1$s" ir pārāk garš: tajā ir %2$d rakstzīmes, bet ierobežojums ir %3$d. Nekas netika nosūtīts; lūdzu, saīsiniet to un mēģiniet vēlreiz.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Norādītais domēns \'%1$s\' neatbilst ne pakotnes manifesta slug \'%2$s\', ne tā text_domain \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Apvienotais indekss \'%s\' tika pārbūvēts, bet tulkojumu indekss to nevarēja ierakstīt; nākamā pārbūve mēģinās vēlreiz.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Oriģinālais teksts un no tā izveidotie tulkojumi tiks nodrošināti citām vietnēm, kas instalē to pašu versiju.','The package declares no main translation file.'=>'Pakotne nedeklarē galveno tulkojuma failu.','The package has no %s for its own text domain.'=>'Pakotnē nav %s tās pašas teksta domēnam.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Pakotnes manifesta veids \'%1$s\' neatbilst pieprasītajam veidam \'%2$s\'.','The package produced no servable main translation file.'=>'Pakotne neradīja nevienu sniedzamu galveno tulkojumu failu.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Pakotnes teksta domēns \'%1$s\' neatbilst šīs vietnes komponenta kopijai (\'%2$s\'), tāpēc tā netika instalēta.','The packaged component could not be read.'=>'Sapakoto komponentu nevarēja nolasīt.','The registration challenge is not in the expected form.'=>'Reģistrācijas izaicinājums nav paredzētajā formā.','The report could not be sent.'=>'Ziņojumu neizdevās nosūtīt.','The search could not be completed.'=>'Meklēšanu neizdevās pabeigt.','The service asked this site to wait before syncing again.'=>'Pakalpojums lūdza šo vietni pagaidīt pirms nākamās sinhronizēšanas.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Pakalpojums nevarēja sasniegt jūsu vietni. Pieprasījumu, iespējams, bloķē ugunsmūris, drošības spraudnis vai resursdatora noteikums; lūdzu, atļaujiet pieprasījumus uz /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Pakalpojuma augšupielādes piedāvājums bija nepilnīgs.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Teksta domēns \'%1$s\' (%2$s) jau tiek sniegts citam instalētam komponentam (%3$s); nekas netika instalēts.','The upload is kept until you ask Babilim to delete it.'=>'Augšupielāde tiek glabāta, līdz lūgsiet Babilim to dzēst.','Theme'=>'Tēma','Theme · %s'=>'Tēma · %s','Themes'=>'Tēmas','There is no upload in progress.'=>'Pašlaik nenotiek augšupielāde.','There is no upload waiting for confirmation.'=>'Nav augšupielādes, kas gaidītu apstiprinājumu.','These are the languages this site uses. You can change them in %s.'=>'Šīs ir valodas, ko izmanto šī vietne. Tās varat mainīt sadaļā %s.','These fields will be sent:'=>'Tiks nosūtīti šie lauki:','This build is not one this site currently knows about for this component/locale.'=>'Šī vietne pašlaik nepazīst šo versiju šim komponentam/lokalizācijai.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Šis komponents nenorāda versijas numuru, tāpēc tam nevar pieprasīt tulkojumu.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Šis komponents ir lielāks, nekā pakalpojums pieņem, tāpēc to nevar augšupielādēt.','This component was already uploaded. Babilim is checking it now.'=>'Šis komponents jau tika augšupielādēts. Babilim to tagad pārbauda.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Šī komponenta versijas numurs ir garāks par %d rakstzīmēm, ko Babilim nevar apstrādāt, tāpēc tam nevar pieprasīt tulkojumu.','This issues a new restore code and the previous one stops working. Continue?'=>'Tiks izsniegts jauns atjaunošanas kods, un iepriekšējais pārstās darboties. Vai turpināt?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Šajā tīklā ir pārāk daudz vietņu, lai tās pārbaudītu pa vienai, un dažas no tām var būt iestatītas izdzēst savu Babilim identitāti, kad spraudnis tiek dzēsts. Šādai vietnei piesaistīto maksas licenci tad nevarētu atjaunot automātiski; jums būtu jāsazinās ar Babilim atbalstu pa adresi %s. Lai saglabātu identitātes, nospiediet Atcelt, katras vietnes Babilim iestatījumos noņemiet atzīmi "Atinstalējot dzēst visus Babilim datus" un deaktivizējiet vēlreiz. Vai tomēr deaktivizēt?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Šī spraudņa paša versija, lai pakalpojums varētu likt jums to atjaunināt, ja tā ir pārāk veca saziņai.','This report does not name a valid plugin or theme and locale.'=>'Šajā ziņojumā nav norādīts derīgs spraudnis vai tēma un lokalizācija.','This report does not name an installed string.'=>'Šajā pārskatā nav norādīta instalētā virkne.','This report is missing a valid build to report against.'=>'Šim ziņojumam trūkst derīgas versijas, par kuru ziņot.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Šis ziņojums tiks publicēts publiski vietnē GitHub, un trešās puses to var saglabāt.','This restore code was not recognised for this site.'=>'Šis atjaunošanas kods šai vietnei netika atpazīts.','This site already has an active registration that can no longer be recovered automatically.'=>'Šai vietnei jau ir aktīva reģistrācija, kuru vairs nevar atjaunot automātiski.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Šajā vietnē ir %1$d komponenti %2$d valodās, kam nepieciešamas %3$d pārbaužu partijas; Babilim vienā reizē var apstrādāt ne vairāk kā %4$d. Samaziniet pārvaldīto valodu skaitu sadaļā Iestatījumi vai deaktivizējiet neizmantotos spraudņus un tēmas, tad nospiediet Pārbaudīt vēlreiz tagad.','This site has no purchase to show a code for.'=>'Šai vietnei nav pirkuma, kuram parādīt kodu.','This site is already licensed. Reload the page.'=>'Šai vietnei jau ir piešķirta licence. Pārlādējiet lapu.','This site is not registered with Babilim yet.'=>'Šī vietne vēl nav reģistrēta pakalpojumā Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Šī vietne pārsniedz izmēru, ko pakalpojums pieņem vienā sinhronizācijā, tāpēc daži vienumi tika izlaisti: %1$d komponenti un %2$d lokalizācijas.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Šī vietne ir daļa no vairākvietņu (multisite) tīkla, kas jaunus tulkojumus neinstalē automātiski. Jau instalētie tulkojumi tomēr tiek atjaunināti.','This site is verified.'=>'Šī vietne ir verificēta.','This site must be verified first.'=>'Šī vietne vispirms ir jāpārbauda.','This site\'s URL, so the service can verify you own it.'=>'Šīs vietnes URL, lai pakalpojums varētu pārbaudīt, ka tā pieder jums.','This site\'s address is too long for Babilim to register.'=>'Šīs vietnes adrese ir pārāk gara, lai Babilim to reģistrētu.','This site\'s configured locale.'=>'Šīs vietnes konfigurētā lokāle.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Šīs vietnes instalācijas publiskā atslēga, ko izmanto, lai pierādītu, ka pieprasījumi patiešām nāk no šīs vietnes. Tiek sūtīta tikai publiskā daļa.','This site\'s locale code is not one Babilim can register.'=>'Šīs vietnes lokalizācijas kodu Babilim nevar reģistrēt.','This string can\'t be reported from this site.'=>'Par šo virkni no šīs vietnes nevar ziņot.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Šīs virknes nav starp šajā vietnē instalētajiem tulkojumiem. Meklējiet vēlreiz un izvēlieties to no saraksta.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Šis tulkojums ir atjaunināts pēc jūsu meklēšanas. Meklējiet vēlreiz un izvēlieties virkni no jaunā saraksta.','To translate this component, Babilim needs its source.'=>'Lai tulkotu šo komponentu, Babilim ir nepieciešams tā avots.','Too many attempts. Try again tomorrow.'=>'Pārāk daudz mēģinājumu. Mēģiniet vēlreiz rīt.','Too many reports today. Try again tomorrow.'=>'Šodien pārāk daudz ziņojumu. Mēģiniet vēlreiz rīt.','Too many requests.'=>'Pārāk daudz pieprasījumu.','Toolbar'=>'Rīkjosla','Translating…'=>'Tulko…','Translation does not load'=>'Tulkojums neielādējas','Translation failed'=>'Tulkošana neizdevās','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Tulkojumu failiem, ko ievietojat %s, vienmēr ir augstāka prioritāte nekā Babilim failiem. Tie tiek saglabāti, ja vien nenoņemat šo atzīmi.','Translation requested.'=>'Tulkojums pieprasīts.','Translations'=>'Tulkojumi','Type'=>'Veids','Type at least 2 characters to search.'=>'Lai meklētu, ievadiet vismaz 2 rakstzīmes.','Unexpected HTTP %d response.'=>'Negaidīta HTTP %d atbilde.','Uninstall'=>'Atinstalēt','Unknown kind: %s'=>'Nezināms veids: %s','Unsafe domain: %s'=>'Nedrošs domēns: %s','Unsafe locale: %s'=>'Nedroša lokāle: %s','Unsafe slug: %s'=>'Nedrošs slug: %s','Unsafe text_domain: %s'=>'Nedrošs text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Līdz 20 gaidošiem diagnostikas notikumiem (piem., par failu, kas neizturēja integritātes pārbaudi); katrs ietver tikai kodu, komponentu un lokāli, bet nekad neietver virkņu saturu vai tulkoto tekstu.','Update'=>'Atjaunināt','Update available'=>'Pieejams atjauninājums','Updates'=>'Atjauninājumi','Updating…'=>'Atjaunina…','Upgrade this site'=>'Jaunināt šo vietni','Upload and request'=>'Augšupielādēt un pieprasīt','Upload cancelled.'=>'Augšupielāde atcelta.','Upload complete — translation requested.'=>'Augšupielāde pabeigta — tulkojums pieprasīts.','Upload expired before it finished'=>'Augšupielādes derīgums beidzās pirms pabeigšanas','Upload in progress — continue or cancel'=>'Notiek augšupielāde — turpiniet vai atceliet','Upload this component?'=>'Vai augšupielādēt šo komponentu?','Upload was not accepted'=>'Augšupielāde netika pieņemta','Uploading'=>'Augšupielādē','Uploading part %1$d of %2$d…'=>'Augšupielādē daļu %1$d no %2$d…','Uploading…'=>'Augšupielādē…','Verified'=>'Pārbaudīts','Verify response was missing site_token.'=>'Pārbaudes atbildē trūka site_token.','Version %s'=>'Versija %s','What is sent when Babilim checks this site'=>'Kas tiek nosūtīts, kad Babilim pārbauda šo vietni','What is sent when you enable Babilim'=>'Kas tiek nosūtīts, kad iespējojat Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Ja Babilim iekšienē kaut kas neizdodas, nosūtiet kļūdas ziņojumu Babilim pakalpojumam, lai to varētu publicēt kā publisku problēmu vietnē GitHub. Ziņojums tiek nosūtīts kā no šīs vietnes ar tādu pašu autentifikāciju kā katram citam pieprasījumam Babilim pakalpojumam. Pakalpojums kā publisku problēmu vietnē GitHub publicē tikai kļūdas kodu un versijas; publiskā problēma nesatur vietnes adresi, saturu vai failu ceļus. Pēc noklusējuma izslēgts.','Where you saw this (optional)'=>'Kur to redzējāt (nav obligāts)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Kamēr šis ir ieslēgts, tulkojumi, kurus pakalpojums norāda kā pieejamus jūsu pārvaldītajām valodām, tiek instalēti sinhronizācijas laikā divreiz dienā.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Nepareizi šajā kontekstā','Wrong meaning'=>'Nepareiza nozīme','Wrong plural form'=>'Nepareiza daudzskaitļa forma','Wrong term'=>'Nepareizs termins','Yes'=>'Jā','You are not allowed to do this.'=>'Jums nav atļaujas to darīt.','Your PHP version, for compatibility.'=>'Jūsu PHP versija saderības nodrošināšanai.','Your WordPress version, to serve compatible translation files.'=>'Jūsu WordPress versija, lai nodrošinātu saderīgus tulkojumu failus.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Jūsu jaunais atjaunošanas kods: %s. Glabājiet to drošā vietā — iepriekšējais kods vairs nedarbojas.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Jūsu ziņojumu automātiski apstrādā AI modeļi, un tas var uzlabot šo tulkojumu citām vietnēm.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Jūsu vietne atbildēja, bet ne ar gaidīto. REST API var būt pārrakstījis cits spraudnis, vai arī šis galapunkts var būt kešots; lūdzu, izslēdziet /wp-json/babilim/v1/challenge no kešošanas un pārrakstīšanas.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Jūsu vietnei bija nepieciešams pārāk ilgs laiks, lai atbildētu. Lūdzu, mēģiniet vēlāk vēlreiz un pārbaudiet, vai jūsu resursdators nav pārāk lēns vai pārslogots.','Zip has no manifest.json.'=>'Zip failā nav manifest.json.','Zip is missing expected default file: %s'=>'Zip arhīvā trūkst gaidītā noklusējuma faila: %s','Zip is missing expected file: %s'=>'Zip arhīvā trūkst gaidītā faila: %s','_manifest.json has an unexpected structure'=>'_manifest.json struktūra ir neparedzēta','could not read _manifest.json: %s'=>'neizdevās nolasīt _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest trūkst lauka \'%s\' vai tas ir nederīgs.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest lauks \'server_build_id\' nav derīgs būvējuma ID.','failed to parse _manifest.json: %s'=>'neizdevās parsēt _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'tas padarītu par bezsaistes ierakstiem %1$d no %2$d pārvaldītajiem komponentiem (vairāk nekā pusi)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'tas padarītu par bezsaistes ierakstiem visus pārvaldītos %1$s komponentus (%2$d no %2$d)','l10n.php entry count mismatch for %s'=>'l10n.php ierakstu skaits nesakrīt failam %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ir nederīgs default_domain_entries.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ir nederīgs \'default_domain_files\'.','manifest.json in the zip is not valid JSON.'=>'manifest.json zip failā nav derīgs JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json trūkst lauka \'%s\' vai tas ir nederīgs.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json trūkst lauka \'build_no\' vai tas ir nederīgs.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json trūkst lauka \'entries\' vai tas ir nederīgs.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json trūkst lauka \'extra_domains\' vai tas ir nederīgs.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json trūkst lauka \'files\' vai tas ir nederīgs.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json lauks \'%s\' neatbilst gaidītajai vērtībai.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json lauks \'contract\' nav derīga versijas virkne.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json laukam \'kind\' jābūt \'plugin\' vai \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json lauks \'server_build_id\' nav derīgs būvējuma ID.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json laukam \'status\' jābūt \'published\'.','nonce must be a hexadecimal string.'=>'Vienreizlietojamajam kodam (nonce) jābūt heksadecimālai virknei.','per day'=>'dienā','rc_…'=>'rc_…','sha256 mismatch for %s'=>'sha256 neatbilstība failam %s','sha256 mismatch for default/%s'=>'sha256 neatbilstība failam default/%s','component kind in the sweep brake messageplugin'=>'spraudņa','component kind in the sweep brake messagetheme'=>'tēmas','problem report categoryOther'=>'Cits','translation statusAvailable'=>'Pieejams','translation statusInstalled'=>'Instalēts']];